package com.unishut.repository;

import com.unishut.model.Bus;
import com.unishut.model.Location;
import com.unishut.model.Trip;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

/**
 * Repository for GPS/location data.
 *
 * Location records are historical GPS readings generated by
 * UniShut buses.
 *
 * The repository is used by:
 *
 * - LocationService
 * - Live tracking
 * - Trip tracking
 * - Bus tracking
 * - Location history
 */
@Repository
public interface LocationRepository
        extends JpaRepository<Location, Long> {


    /**
     * Find the latest GPS location of a bus.
     *
     * Spring Data sorts the records by recordedAt in
     * descending order and returns only the first result.
     */
    Optional<Location> findFirstByBusOrderByRecordedAtDesc(
            Bus bus
    );


    /**
     * Find the latest GPS location of a trip.
     */
    Optional<Location> findFirstByTripOrderByRecordedAtDesc(
            Trip trip
    );


    /**
     * Find the latest GPS location for a specific
     * bus and trip combination.
     */
    Optional<Location>
    findFirstByBusAndTripOrderByRecordedAtDesc(
            Bus bus,
            Trip trip
    );


    /**
     * Find all GPS records for a bus.
     *
     * Newest locations are returned first.
     *
     * This method is useful for:
     *
     * - Location history
     * - Route replay
     * - Admin tracking
     * - Debugging GPS devices
     */
    List<Location>
    findByBusOrderByRecordedAtDesc(
            Bus bus
    );


    /**
     * Find all GPS records for a trip.
     *
     * Newest locations are returned first.
     */
    List<Location>
    findByTripOrderByRecordedAtDesc(
            Trip trip
    );


    /**
     * Find recent GPS locations for a bus.
     *
     * This query is intentionally ordered by recordedAt
     * so that LocationService can safely apply a limit.
     */
    @Query("""
            SELECT l
            FROM Location l
            WHERE l.bus = :bus
            ORDER BY l.recordedAt DESC
            """)
    List<Location> findRecentLocationsByBus(
            @Param("bus") Bus bus
    );


    /**
     * Find recent GPS locations for a trip.
     */
    @Query("""
            SELECT l
            FROM Location l
            WHERE l.trip = :trip
            ORDER BY l.recordedAt DESC
            """)
    List<Location> findRecentLocationsByTrip(
            @Param("trip") Trip trip
    );


    /**
     * Count the number of GPS records received for a bus.
     */
    long countByBus(
            Bus bus
    );


    /**
     * Count the number of GPS records received for a trip.
     */
    long countByTrip(
            Trip trip
    );


    /**
     * Delete location history belonging to a bus.
     *
     * This should normally be used only by administrative
     * cleanup operations.
     */
    long deleteByBus(
            Bus bus
    );


    /**
     * Delete location history belonging to a trip.
     *
     * This should normally be used only when historical
     * location data is intentionally removed.
     */
    long deleteByTrip(
            Trip trip
    );
}